import{_ as a,o,c as t,a0 as n}from"./chunks/framework.Zkdr1e1x.js";const h=JSON.parse('{"title":"ADR 0002: Package-by-Feature for Low-Level Designs (LLD)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0002-package-by-feature-in-lld.md","filePath":"adr/0002-package-by-feature-in-lld.md"}'),r={name:"adr/0002-package-by-feature-in-lld.md"};function l(s,e,i,c,d,u){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0002-package-by-feature-for-low-level-designs-lld" tabindex="-1">ADR 0002: Package-by-Feature for Low-Level Designs (LLD) <a class="header-anchor" href="#adr-0002-package-by-feature-for-low-level-designs-lld" aria-label="Permalink to &quot;ADR 0002: Package-by-Feature for Low-Level Designs (LLD)&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Layered packaging (e.g., placing all <code>models</code> across all problems in one package and all <code>services</code> in another) breaks encapsulation and makes individual design problems hard to read and evaluate.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Package every LLD problem independently (<code>dev.anurag.handbook.lld.&lt;system&gt;</code>), collocating model, service, repository, and strategy within that problem&#39;s namespace.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><strong>Positive</strong>: High cohesion; each problem is completely self-contained and modular.</li><li><strong>Negative</strong>: Minor duplication of generic value objects (e.g., <code>Direction</code>).</li></ul>',9)])])}const g=a(r,[["render",l]]);export{h as __pageData,g as default};
